{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C17"],
      "claim": "Meperidine absolute oral bioavailability in healthy volunteers is 0.56, well above the 20% threshold, supporting high F for a basic amine-containing molecule.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Trazodone absolute oral bioavailability is approximately 80% in humans, supporting high F for a molecule with an aryl piperazine and chlorophenyl group.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Alogliptin has an absolute bioavailability of ≈100% in healthy volunteers, supporting high F for a small, orally absorbed drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Levamisole absolute oral bioavailability is 0.71 in cancer patients, supporting high F for a lipophilic, basic, rigid molecule.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Delpazolid absolute oral bioavailability is 99.75% after an 800 mg oral dose, supporting high F for a molecule with a basic amine and aromatic heterocycle.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C55"],
      "claim": "Ranolazine oral bioavailability from slow-release tablets is 35–50%, above the 20% threshold, supporting high F for a lipophilic aromatic ether.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Vorozole has excellent oral bioavailability in postmenopausal women, supporting high F for a lipophilic azole with a chlorophenyl group.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "2,4-D is rapidly and completely absorbed orally in humans, supporting high F for a small, lipophilic aromatic acid.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "NNC 01-0687 achieves high oral bioavailability in humans, supporting high F for a rigid, basic, polycyclic amine.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Meptazinol absolute oral bioavailability is 4.4%, below the threshold, but this low value is driven by first-pass phenolic glucuronidation, a metabolic liability absent in the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The preponderance of high-transfer human absolute bioavailability evidence (meperidine, trazodone, alogliptin, levamisole, delpazolid, ranolazine, vorozole, 2,4-D, NNC 01-0687) supports F ≥20%. The only low-F analogue, meptazinol, owes its poor bioavailability to first-pass phenolic glucuronidation, a liability absent in the query, which has no hydrogen-bond donors and very low TPSA. Therefore predict high.",
  "evidence_gaps": [
    "No direct human oral bioavailability measurement for the query molecule.",
    "No data on first-pass metabolism or efflux for the query.",
    "The low-F meptazinol evidence is mechanistically not transferable due to the phenolic OH."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

